void bhEne01_Nage(BH_PWORK* epw)
{
	EXP0_I(0x40) &= ~0x800;
	if (EXP0_I(0x44) & 0x80)
    {
		EXP0_I(0x44) &= ~0x80;
	}
    
	if (EXP0_I(0x40) & 0x80000000)
    {
		bhEne01_NageTypeB[epw->type](epw);
	} 
    else
    {
		bhEne01_NageTypeW[epw->type](epw);
	}
}

