    ps.x = plp->px;
    ps.y = 0.5f + plp->py;
    ps.z = plp->pz;
    *(ATR_WORK**)(epw->exp0 + 0x70) = bhCollisionCheckLine((NJS_VECTOR*)&epw->px, &ps);

    t = EXP0_I(0x40) & 0xF;
    
