            ops.x = (ops.x + owk[17].mtx[12]) / 2.0f;
            ops.z = (ops.z + owk[17].mtx[14]) / 2.0f;
            ops.y = epw->pyb; 
                       
            bhEne_CalcPartsPos(epw, lcmat, &ps, en01_tree[2], 7, 1);
            bhEne_CalcPartsPos(epw, lcmat, &pd, en01_tree[3], 7, 1);

            ps.x = (ps.x + pd.x) / 2.0f;
