// 100% matching!
void bhEne01_KamiEffect(BH_PWORK* epw, int frm)
{
	EN01_KAMI_WORK* keff;
	NJS_POINT3 pd;
	int i;
	int j;

	keff = en01_keff_tbl;
    
	for (i = 0; TRUE; i++, keff++) 
	{
		if (keff->mtn_no == -1)
        {
            return;
        }
			
		if (epw->mtn_no == keff->mtn_no)
		{
            for (j = 0; j < 4; j++)
            {
                if (frm == keff->frm[j])
                {
                	pd.x = 0.0f;
                	pd.y = 0.0f;
                	pd.z = -1.8f;
                
                	epw->djnt_no = 11;
                	bhEne_SetBlood2(epw, 1, &pd, 0);
                
                	if (j == 0)
                	{
                		epw->djnt_no = 11;
                		bhEne_SetBlood2(epw, 4, &pd, epw->ay);
                	}
                
                	return;
                }
            }
		}
	}
}

// 99.62% matching
void bhEne01_WaterEffect(BH_PWORK* epw, int frm)
{
	EN01_WATER_WORK* weff;
	O_WORK* owk;
	NJS_POINT3 pd; 
	NJS_POINT3 ps;  
	int i;
	int j;

    weff = en01_weff_tbl;
    
    if (epw->stflg & 0x100000)
    {
    	for (j = 0; TRUE; j++, weff++) 
    	{
    		if (weff->mtn_no == -1)
            {
                return;
            }
            
            if (epw->mtn_no == weff->mtn_no) 
            {
                for (i = 0; i < 3; i++)            
                {
                    if (weff->eff[i].frm == -1)
                    {
                        return;
                    } 
                    
                    if (weff->eff[i].frm == frm)
                    {
                        if (weff->eff[i].size != -1)
                        {
                            bhSetEffect(108, (POINT*)&epw->mlwP->owP->mtx[12], NULL, weff->eff[i].size);
                        }
                        
                        if (weff->eff[i].obj != -1)
                        {
                            ps.x = weff->eff[i].px;
                            ps.z = weff->eff[i].pz;
                            
                            njUnitMatrix(NULL);
                            njRotateY(NULL, epw->ay);
                            njCalcPoint(NULL, &ps, &pd);
                            
                            owk = &epw->mlwP->owP[weff->eff[i].obj];
                            pd.x = owk->mtx[12] - pd.x;
                            pd.y = owk->mtx[13];
                            pd.z = owk->mtx[14] - pd.z;
                            
                            if (weff->eff[i].size < 11)
                            {
                                bhSetWaterSplash2(epw, &pd, 1, 0.8f, 0.8f, 0.8f);
                            } 
                            else if (weff->eff[i].size < 13)
                            {
                                bhSetWaterSplash2(epw, &pd, 1, 1.4f, 1.4f, 1.4f);
                            } 
                            else
                            {
                                bhSetWaterSplash2(epw, &pd, 1, 2.0f, 2.0f, 2.0f);
                            }                                
                        }
                    }                    
                }              
            }         
        }
    }
}

