// 100% matching!
int bhEne01_ChgTextID(BH_PWORK* epw, int tex_id)
{
    if (epw->mdlver == 2 ||
        epw->mdlver == 3 ||
        epw->mdlver == 9 ||
        epw->mdlver == 10 ||
        epw->mdlver == 32 ||
        epw->mdlver == 33 ||
        epw->mdlver == 39 ||
        epw->mdlver == 43)
    {
        return tex_id;
    }

    if (epw->mdlver == 4 ||
        epw->mdlver == 21 ||
        epw->mdlver == 34)
    {
        return tex_id + 1;
    }

    if (epw->mdlver == 7 ||
        epw->mdlver == 8 ||
        epw->mdlver == 31 ||
        epw->mdlver == 37 ||
        epw->mdlver == 38 ||
        epw->mdlver == 42)
    {
        return tex_id + 2;
    }

    if (epw->mdlver == 0 ||
        epw->mdlver == 1 ||
        epw->mdlver == 5 ||
        epw->mdlver == 6 ||
        epw->mdlver == 22 ||
        epw->mdlver == 35 ||
        epw->mdlver == 36)
    {
        return tex_id + 3;
    }

    if (epw->mdlver == 40)
    {
        return tex_id + 4;
    }

    return tex_id + 5;
}

